mkdir -p /app/output && cat > /app/output/index.html <<'EOF'
<!doctype html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>SnapFrame — Capture, Create & Share What You Love</title>
  <meta name="description" content="SnapFrame is a social media platform that makes it easy to capture, create, and share what you love with the people who matter most." />
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&family=Plus+Jakarta+Sans:wght@600;700;800&display=swap" rel="stylesheet">
  <style>
    :root {
      --bg: #f8f9ff;
      --surface: #ffffff;
      --text: #131320;
      --muted: #585d73;
      --line: #e6e9f5;
      --primary: #7d35ff;
      --primary-2: #ff2e9a;
      --accent: #ff8a1f;
      --safe-bg: #f2f8ff;
      --creator-bg: #fff5fb;
      --radius: 18px;
      --shadow: 0 10px 30px rgba(33, 38, 74, 0.09);
      --container: min(1160px, calc(100% - 2rem));
    }

    * { box-sizing: border-box; }
    html, body { margin: 0; padding: 0; }
    body {
      font-family: Inter, system-ui, -apple-system, Segoe UI, Roboto, sans-serif;
      color: var(--text);
      background: linear-gradient(180deg, #fff 0%, #fafbff 100%);
      line-height: 1.45;
    }

    a { color: inherit; text-decoration: none; }
    img { max-width: 100%; display: block; }

    .container { width: var(--container); margin-inline: auto; }
    .section { padding: 4.5rem 0; }
    .section-title {
      font-family: "Plus Jakarta Sans", Inter, sans-serif;
      font-size: clamp(1.75rem, 3vw, 2.4rem);
      line-height: 1.15;
      margin: 0 0 0.8rem;
      letter-spacing: -0.02em;
    }
    .section-desc { color: var(--muted); margin: 0; max-width: 66ch; }

    .topbar {
      position: sticky;
      top: 0;
      z-index: 30;
      background: rgba(255,255,255,0.84);
      backdrop-filter: blur(10px);
      border-bottom: 1px solid rgba(230,233,245,0.7);
    }
    .nav-wrap {
      height: 76px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 1rem;
    }
    .brand {
      display: inline-flex;
      align-items: center;
      gap: .65rem;
      font-weight: 800;
      letter-spacing: -0.02em;
      font-family: "Plus Jakarta Sans", Inter, sans-serif;
      font-size: 1.15rem;
    }
    .brand-mark {
      width: 32px;
      height: 32px;
      border-radius: 10px;
      background: linear-gradient(135deg, var(--primary) 0%, var(--primary-2) 48%, var(--accent) 100%);
      box-shadow: 0 6px 18px rgba(125, 53, 255, 0.33);
    }
    .nav-links {
      display: flex;
      align-items: center;
      gap: 1.2rem;
      color: #30344a;
      font-weight: 500;
    }
    .nav-links a { padding: .45rem .35rem; border-radius: 8px; }
    .nav-links a:hover { background: #f3f5ff; }

    .actions { display: flex; align-items: center; gap: .7rem; }
    .btn {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      border: 1px solid transparent;
      border-radius: 999px;
      padding: .72rem 1.2rem;
      font-weight: 600;
      cursor: pointer;
      transition: transform .18s ease, box-shadow .18s ease, background .18s ease;
      white-space: nowrap;
    }
    .btn:hover { transform: translateY(-1px); }
    .btn:focus-visible { outline: 2px solid #271f82; outline-offset: 2px; }
    .btn-primary {
      color: #fff;
      background: linear-gradient(120deg, var(--primary), var(--primary-2));
      box-shadow: 0 10px 22px rgba(125,53,255,.28);
    }
    .btn-light {
      color: #22263d;
      background: #f2f4fb;
      border-color: #e3e7f5;
    }

    .menu-btn {
      width: 42px;
      height: 42px;
      border-radius: 12px;
      border: 1px solid #dee3f5;
      background: #fff;
      display: none;
      align-items: center;
      justify-content: center;
      cursor: pointer;
    }
    .menu-btn span,
    .menu-btn::before,
    .menu-btn::after {
      content: "";
      display: block;
      width: 18px;
      height: 2px;
      background: #272a42;
      border-radius: 2px;
      position: absolute;
      transition: transform .2s ease, opacity .2s ease;
    }
    .menu-btn span { position: relative; }
    .menu-btn::before { transform: translateY(-6px); }
    .menu-btn::after { transform: translateY(6px); }
    .menu-btn[aria-expanded="true"] span { opacity: 0; }
    .menu-btn[aria-expanded="true"]::before { transform: rotate(45deg); }
    .menu-btn[aria-expanded="true"]::after { transform: rotate(-45deg); }

    .mobile-panel {
      display: none;
      border-top: 1px solid var(--line);
      background: #fff;
    }
    .mobile-panel.open { display: block; }
    .mobile-nav {
      width: var(--container);
      margin-inline: auto;
      display: grid;
      gap: .4rem;
      padding: 1rem 0 1.2rem;
    }
    .mobile-nav a {
      padding: .75rem .25rem;
      color: #2c3048;
      font-weight: 500;
    }

    .hero {
      padding: 4.7rem 0 3.8rem;
      position: relative;
      overflow: clip;
    }
    .hero::before {
      content: "";
      position: absolute;
      inset: -120px auto auto 50%;
      transform: translateX(-38%);
      width: min(900px, 92vw);
      height: 420px;
      background:
        radial-gradient(circle at 20% 45%, rgba(255,46,154,.35), transparent 48%),
        radial-gradient(circle at 72% 30%, rgba(125,53,255,.35), transparent 46%),
        radial-gradient(circle at 55% 80%, rgba(255,138,31,.28), transparent 45%);
      z-index: -1;
      filter: saturate(115%);
    }
    .hero-grid {
      display: grid;
      grid-template-columns: 1.1fr .9fr;
      align-items: center;
      gap: 2rem;
    }
    .eyebrow {
      display: inline-flex;
      align-items: center;
      gap: .5rem;
      font-size: .82rem;
      font-weight: 700;
      letter-spacing: .08em;
      text-transform: uppercase;
      color: #6e42dc;
      background: #efe8ff;
      border: 1px solid #e1d2ff;
      border-radius: 999px;
      padding: .42rem .75rem;
      margin-bottom: .9rem;
    }
    h1 {
      font-family: "Plus Jakarta Sans", Inter, sans-serif;
      font-size: clamp(2.2rem, 6vw, 4.05rem);
      line-height: 1.05;
      letter-spacing: -0.03em;
      margin: 0;
      max-width: 14ch;
    }
    .hero-copy p {
      margin: 1rem 0 1.6rem;
      color: #444b66;
      max-width: 55ch;
      font-size: clamp(1rem, 2.1vw, 1.14rem);
    }
    .hero-actions { display: flex; gap: .75rem; flex-wrap: wrap; }
    .hero-card {
      background: var(--surface);
      border: 1px solid #e9ecf8;
      border-radius: 26px;
      box-shadow: var(--shadow);
      padding: 1.2rem;
    }
    .hero-media {
      border-radius: 18px;
      min-height: 320px;
      background:
        linear-gradient(145deg, rgba(125,53,255,.95), rgba(255,46,154,.88) 55%, rgba(255,138,31,.9));
      position: relative;
      overflow: hidden;
      isolation: isolate;
    }
    .hero-media::before,
    .hero-media::after {
      content: "";
      position: absolute;
      border-radius: 999px;
      filter: blur(1px);
      opacity: .92;
    }
    .hero-media::before {
      width: 240px;
      height: 240px;
      right: -35px;
      top: -38px;
      background: radial-gradient(circle, rgba(255,255,255,.35), transparent 65%);
    }
    .hero-media::after {
      width: 160px;
      height: 160px;
      left: -20px;
      bottom: -25px;
      background: radial-gradient(circle, rgba(255,255,255,.3), transparent 62%);
    }
    .floating-stats {
      position: absolute;
      inset: auto 1rem 1rem 1rem;
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: .6rem;
    }
    .stat {
      background: rgba(255,255,255,.92);
      border: 1px solid rgba(255,255,255,.7);
      border-radius: 12px;
      padding: .65rem .6rem;
      text-align: center;
      backdrop-filter: blur(4px);
    }
    .stat strong { display: block; font-size: 1rem; }
    .stat span { font-size: .75rem; color: #525970; }

    .cards-3 {
      margin-top: 2rem;
      display: grid;
      gap: 1rem;
      grid-template-columns: repeat(3, minmax(0, 1fr));
    }
    .feature-card {
      border: 1px solid var(--line);
      background: #fff;
      border-radius: var(--radius);
      padding: 1.15rem;
      box-shadow: 0 6px 18px rgba(45,57,102,.05);
    }
    .pill {
      display: inline-flex;
      align-items: center;
      gap: .4rem;
      font-size: .75rem;
      font-weight: 700;
      letter-spacing: .04em;
      text-transform: uppercase;
      border-radius: 999px;
      padding: .28rem .56rem;
      background: #f0eaff;
      color: #6334d1;
      margin-bottom: .55rem;
    }
    .feature-card h3 { margin: .2rem 0 .4rem; font-size: 1.1rem; }
    .feature-card p { margin: 0; color: var(--muted); }

    .safety { background: var(--safe-bg); border-block: 1px solid #e1ecff; }
    .creators { background: var(--creator-bg); border-block: 1px solid #f7d8ec; }

    .split {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 1.2rem;
      align-items: center;
    }

    .tagline-banner {
      padding: 2rem 0;
      background: linear-gradient(90deg, #3f1ab8, #8d2df6 45%, #ff3b90 70%, #ff8a1f);
      color: #fff;
      text-align: center;
      font-family: "Plus Jakarta Sans", Inter, sans-serif;
      font-weight: 700;
      letter-spacing: -0.01em;
      font-size: clamp(1.05rem, 2.8vw, 1.52rem);
    }

    .news-head {
      display: flex;
      align-items: end;
      justify-content: space-between;
      gap: 1rem;
      margin-bottom: 1.1rem;
    }
    .news-link {
      color: #5426d4;
      font-weight: 700;
      font-size: .95rem;
    }

    .news-track {
      display: grid;
      grid-auto-flow: column;
      grid-auto-columns: minmax(250px, 31%);
      gap: 1rem;
      overflow-x: auto;
      overscroll-behavior-x: contain;
      scroll-snap-type: x mandatory;
      padding: .25rem .1rem .8rem;
      scrollbar-width: thin;
      scrollbar-color: #d6d9e8 transparent;
      -webkit-overflow-scrolling: touch;
    }
    .news-track::-webkit-scrollbar { height: 10px; }
    .news-track::-webkit-scrollbar-thumb { background: #d6d9e8; border-radius: 999px; }
    .news-card {
      scroll-snap-align: start;
      border: 1px solid var(--line);
      border-radius: 16px;
      background: #fff;
      overflow: hidden;
      box-shadow: 0 8px 22px rgba(55,60,100,.07);
    }
    .thumb {
      aspect-ratio: 16 / 10;
      background: linear-gradient(130deg, #9f7bff, #ff57b2 55%, #ffab4c);
      position: relative;
    }
    .thumb::after {
      content: "";
      position: absolute;
      inset: 0;
      background: radial-gradient(circle at 20% 20%, rgba(255,255,255,.35), transparent 38%),
                  radial-gradient(circle at 85% 85%, rgba(255,255,255,.2), transparent 30%);
    }
    .news-body { padding: .85rem .9rem 1rem; }
    .tags { display: flex; flex-wrap: wrap; gap: .35rem; margin-bottom: .55rem; }
    .tag {
      font-size: .67rem;
      font-weight: 700;
      letter-spacing: .03em;
      text-transform: uppercase;
      border-radius: 999px;
      padding: .28rem .5rem;
      background: #f2ecff;
      color: #5f34cf;
    }
    .news-title {
      margin: 0 0 .6rem;
      font-size: 1rem;
      line-height: 1.35;
      letter-spacing: -0.01em;
      min-height: 2.6em;
    }
    .date { margin: 0; color: #666d87; font-size: .87rem; }

    .cta {
      text-align: center;
      background: #11132a;
      color: #fff;
      border-radius: 24px;
      padding: 2.8rem 1.2rem;
    }
    .cta h2 { margin: 0 0 .4rem; font-size: clamp(1.8rem, 3.5vw, 2.5rem); }
    .cta p { margin: 0 0 1.2rem; color: #cfd4ed; }

    footer {
      margin-top: 4rem;
      border-top: 1px solid var(--line);
      background: #fff;
    }
    .footer-grid {
      display: grid;
      grid-template-columns: repeat(6, minmax(0, 1fr));
      gap: 1rem;
      padding: 2.2rem 0;
    }
    .footer-col h4 {
      margin: 0 0 .6rem;
      font-size: .88rem;
      text-transform: uppercase;
      letter-spacing: .05em;
      color: #444c69;
    }
    .footer-col a {
      display: block;
      padding: .28rem 0;
      color: #222a45;
      font-size: .94rem;
    }
    .footer-col a:hover { color: #5b2dd1; }

    .footer-bottom {
      border-top: 1px solid var(--line);
      padding: 1rem 0 1.4rem;
      display: flex;
      align-items: center;
      justify-content: space-between;
      flex-wrap: wrap;
      gap: .9rem;
      font-size: .9rem;
      color: #4f5673;
    }
    .socials { display: flex; gap: .5rem; }
    .soc {
      width: 32px;
      height: 32px;
      border-radius: 10px;
      border: 1px solid #dbe0f1;
      display: inline-flex;
      align-items: center;
      justify-content: center;
      font-size: .82rem;
      font-weight: 700;
      background: #fff;
    }
    .legal { display: flex; gap: .75rem; flex-wrap: wrap; }

    @media (max-width: 1024px) {
      .hero-grid { grid-template-columns: 1fr; }
      .split { grid-template-columns: 1fr; }
      .footer-grid { grid-template-columns: repeat(3, minmax(0,1fr)); }
      .news-track { grid-auto-columns: minmax(260px, 45%); }
    }

    @media (max-width: 760px) {
      .nav-links, .actions .btn-light { display: none; }
      .menu-btn { display: inline-flex; position: relative; }
      .cards-3 { grid-template-columns: 1fr; }
      .footer-grid { grid-template-columns: repeat(2, minmax(0,1fr)); }
      .news-track { grid-auto-columns: minmax(250px, 82%); }
      .section { padding: 3.4rem 0; }
      .hero { padding-top: 3.6rem; }
    }

    @media (max-width: 520px) {
      .footer-grid { grid-template-columns: 1fr; }
      .hero-actions .btn { width: 100%; }
      .floating-stats { grid-template-columns: 1fr 1fr; }
    }
  </style>
</head>
<body>
  <header class="topbar">
    <div class="container nav-wrap">
      <a href="index.html" class="brand" aria-label="SnapFrame home">
        <span class="brand-mark" aria-hidden="true"></span>
        <span>SnapFrame</span>
      </a>

      <nav class="nav-links" aria-label="Primary">
        <a href="#features">Features</a>
        <a href="#safety">Safety</a>
        <a href="#creators">Creators</a>
        <a href="#news">News</a>
      </nav>

      <div class="actions">
        <a class="btn btn-light" href="index.html">Log in</a>
        <a class="btn btn-primary" href="#hero">Try it now</a>
        <button class="menu-btn" id="menuBtn" aria-label="Open menu" aria-controls="mobilePanel" aria-expanded="false">
          <span></span>
        </button>
      </div>
    </div>

    <div id="mobilePanel" class="mobile-panel" hidden>
      <nav class="mobile-nav" aria-label="Mobile">
        <a href="#features">Features</a>
        <a href="#safety">Safety tools</a>
        <a href="#creators">Creator</a>
        <a href="#news">News</a>
        <a href="index.html">Log in</a>
        <a href="#hero">Try it now</a>
      </nav>
    </div>
  </header>

  <main>
    <section class="hero" id="hero">
      <div class="container hero-grid">
        <div class="hero-copy">
          <span class="eyebrow">About SnapFrame</span>
          <h1>Capture, create & share what you love.</h1>
          <p>SnapFrame is a social media platform that makes it easy to capture, create, and share what you love with the people who matter most.</p>
          <div class="hero-actions">
            <a class="btn btn-primary" href="index.html">Try it now</a>
            <a class="btn btn-light" href="#features">Explore features</a>
          </div>
        </div>

        <div class="hero-card" aria-hidden="true">
          <div class="hero-media">
            <div class="floating-stats">
              <div class="stat"><strong>2B+</strong><span>photos shared</span></div>
              <div class="stat"><strong>150M</strong><span>creators</span></div>
              <div class="stat"><strong>190</strong><span>countries</span></div>
            </div>
          </div>
        </div>
      </div>
    </section>

    <section id="features" class="section container">
      <h2 class="section-title">Designed to help people connect through visual storytelling.</h2>
      <p class="section-desc">From Clips and Stories to DMs and Search & Explore, SnapFrame helps people express themselves, discover communities, and build real connections.</p>
      <div class="cards-3">
        <article class="feature-card">
          <span class="pill">Clips</span>
          <h3>Short-form creativity</h3>
          <p>Create and discover fun, immersive short videos designed for modern attention spans.</p>
        </article>
        <article class="feature-card">
          <span class="pill">Stories</span>
          <h3>Everyday moments</h3>
          <p>Share daily highlights that disappear, helping people post naturally and stay in touch.</p>
        </article>
        <article class="feature-card">
          <span class="pill">Messaging</span>
          <h3>Private by default</h3>
          <p>Build close relationships with fast, expressive DMs and controls that put users first.</p>
        </article>
      </div>
      <p style="margin-top:1rem;"><a class="news-link" href="index.html">Features link →</a></p>
    </section>

    <section id="safety" class="section safety">
      <div class="container split">
        <div>
          <h2 class="section-title">Safety tools built for teens, parents, and peace of mind.</h2>
          <p class="section-desc">SnapFrame invests in account protections, privacy controls, and Family Center education so communities can create safely and confidently.</p>
          <p style="margin-top:1rem;"><a class="news-link" href="index.html">Safety tools link →</a></p>
        </div>
        <div class="cards-3" style="margin-top:0; grid-template-columns:1fr;">
          <article class="feature-card"><h3>Teen Accounts</h3><p>Age-appropriate defaults and support for healthy social habits.</p></article>
          <article class="feature-card"><h3>Privacy controls</h3><p>Simple account settings for visibility, comments, and interactions.</p></article>
          <article class="feature-card"><h3>Account security</h3><p>Tools like login alerts and two-step verification keep profiles secure.</p></article>
        </div>
      </div>
    </section>

    <section id="creators" class="section creators">
      <div class="container split">
        <div>
          <h2 class="section-title">Where creators build communities and businesses grow.</h2>
          <p class="section-desc">SnapFrame empowers creators and brands with monetization pathways, audience insights, and storytelling formats that inspire action.</p>
          <p style="margin-top:1rem;"><a class="news-link" href="index.html">Creator link →</a></p>
        </div>
        <div class="hero-card">
          <h3 style="margin:.2rem 0 .6rem;">Creator ecosystem</h3>
          <p class="section-desc">Tools for partnerships, publishing cadence, and campaign performance all in one place.</p>
          <div class="cards-3" style="grid-template-columns:1fr 1fr; margin-top:1rem;">
            <article class="feature-card"><span class="pill">Insights</span><p>Understand reach and engagement.</p></article>
            <article class="feature-card"><span class="pill">Partnerships</span><p>Collaborate with trusted brands.</p></article>
          </div>
        </div>
      </div>
    </section>

    <section class="tagline-banner">Bringing you closer to the people and things you love.</section>

    <section id="news" class="section">
      <div class="container">
        <div class="news-head">
          <div>
            <h2 class="section-title" style="margin-bottom:.3rem;">Latest News</h2>
            <p class="section-desc">Updates from across SnapFrame, product innovation, and community safety.</p>
          </div>
          <a class="news-link" href="index.html">View more →</a>
        </div>

        <div class="news-track" aria-label="SnapFrame news carousel" id="newsTrack">
          <article class="news-card">
            <div class="thumb" aria-hidden="true"></div>
            <div class="news-body">
              <div class="tags"><span class="tag">#Creators</span><span class="tag">#Announcements</span></div>
              <h3 class="news-title">Close Friends Only Podcast — A New Kind of Creative Conversation</h3>
              <p class="date">February 18, 2026</p>
            </div>
          </article>

          <article class="news-card">
            <div class="thumb" aria-hidden="true"></div>
            <div class="news-body">
              <div class="tags"><span class="tag">#Tips & Tricks</span><span class="tag">#Product</span></div>
              <h3 class="news-title">Sticker Ideas and Tips for Finding the Best Ones</h3>
              <p class="date">February 4, 2026</p>
            </div>
          </article>

          <article class="news-card">
            <div class="thumb" aria-hidden="true"></div>
            <div class="news-body">
              <div class="tags"><span class="tag">#Product</span><span class="tag">#Announcements</span></div>
              <h3 class="news-title">Watch Reels on the Big Screen — Introducing SnapFrame for TV</h3>
              <p class="date">December 17, 2025</p>
            </div>
          </article>

          <article class="news-card">
            <div class="thumb" aria-hidden="true"></div>
            <div class="news-body">
              <div class="tags"><span class="tag">#Announcements</span><span class="tag">#Safety</span></div>
              <h3 class="news-title">Carversations: Real Parent-Teen Talks About Social Media</h3>
              <p class="date">December 12, 2025</p>
            </div>
          </article>
        </div>
      </div>
    </section>

    <section class="section container">
      <div class="cta">
        <h2>Create, share and connect.</h2>
        <p>Download now.</p>
        <div class="hero-actions" style="justify-content:center;">
          <a class="btn btn-primary" href="index.html">App Store</a>
          <a class="btn btn-light" href="index.html" style="background:#fff;">Google Play</a>
        </div>
      </div>
    </section>
  </main>

  <footer>
    <div class="container footer-grid">
      <div class="footer-col">
        <h4>About</h4>
        <a href="index.html">Our story</a>
        <a href="index.html">Leadership</a>
