  <script>
    const menuBtn = document.getElementById('menuBtn');
    const mobilePanel = document.getElementById('mobilePanel');

    menuBtn.addEventListener('click', () => {
      const expanded = menuBtn.getAttribute('aria-expanded') === 'true';
      menuBtn.setAttribute('aria-expanded', String(!expanded));
      mobilePanel.hidden = expanded;
      mobilePanel.classList.toggle('open', !expanded);
    });

    mobilePanel.querySelectorAll('a').forEach((link) => {
      link.addEventListener('click', () => {
        menuBtn.setAttribute('aria-expanded', 'false');
        mobilePanel.hidden = true;
        mobilePanel.classList.remove('open');
      });
    });

    const newsTrack = document.getElementById('newsTrack');
    let pointerDown = false;
    let startX = 0;
    let scrollLeft = 0;

    newsTrack.addEventListener('pointerdown', (event) => {
      pointerDown = true;
      newsTrack.setPointerCapture(event.pointerId);
      startX = event.clientX;
      scrollLeft = newsTrack.scrollLeft;
      newsTrack.style.scrollBehavior = 'auto';
    });

    newsTrack.addEventListener('pointermove', (event) => {
      if (!pointerDown) return;
      const distance = event.clientX - startX;
      newsTrack.scrollLeft = scrollLeft - distance;
    });

    const finishDrag = () => {
      pointerDown = false;
      newsTrack.style.scrollBehavior = '';
    };

    newsTrack.addEventListener('pointerup', finishDrag);
    newsTrack.addEventListener('pointercancel', finishDrag);
    newsTrack.addEventListener('pointerleave', finishDrag);
  </script>
